starter_files.style.css:
body {
  margin: 0;
  padding: 0;
  background-color: #0f172a;
  color: #f8fafc;
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  display: flex;
  justify-content: center;
  align-items: center;
  height: 100vh;
}

.counter-card {
  background: #1e293b;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 16px;
  padding: 32px;
  text-align: center;
  box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.5);
  width: 320px;
}

.counter-card h2 {
  font-size: 20px;
  margin-bottom: 8px;
  color: #38bdf8;
}

.counter-card p {
  font-size: 13px;
  color: #94a3b8;
  margin-bottom: 24px;
}

.display-box {
  font-size: 48px;
  font-weight: 700;
  color: #34d399;
  background: #0f172a;
  padding: 16px;
  border-radius: 12px;
  margin-bottom: 24px;
  border: 1px solid rgba(255, 255, 255, 0.05);
}

.btn-group {
  display: flex;
  gap: 8px;
  justify-content: center;
}

.btn-group button {
  flex: 1;
  padding: 10px 14px;
  border: none;
  border-radius: 8px;
  font-weight: 600;
  cursor: pointer;
  background: #3b82f6;
  color: white;
  transition: background 0.2s;
}

.btn-group button:hover {
  background: #2563eb;
}

#resetBtn {
  background: #64748b;
}

#resetBtn:hover {
  background: #475569;
}

starter_files.script.js:
// Aethon IDE Debugging Challenge: Fix the Counter Bug
let count = 0;

function updateDisplay() {
  const displayEl = document.getElementById("countDisplay");
  if (displayEl) {
    displayEl.textContent = count;
  }
}

// BUG 1: String concatenation instead of integer addition ("01" instead of 1)
function increment() {
  count = count + "1"; // BUG: Should be integer 1, not string "1"
  updateDisplay();
}

function decrement() {
  count = parseInt(count) - 1;
  updateDisplay();
}

function reset() {
  count = 0;
  updateDisplay();
}

// BUG 2: Typo in event listener event name ("clik" instead of "click")
document.addEventListener("DOMContentLoaded", () => {
  const incBtn = document.getElementById("incrementBtn");
  const decBtn = document.getElementById("decrementBtn");
  const rstBtn = document.getElementById("resetBtn");

  if (incBtn) incBtn.addEventListener("click", increment);
  if (decBtn) decBtn.addEventListener("clik", decrement); // BUG: Typo "clik" instead of "click"
  if (rstBtn) rstBtn.addEventListener("click", reset);
});

if (typeof module !== "undefined" && module.exports) {
  module.exports = { increment, decrement, reset, getCount: () => count };
}
